package com.sacco.mvp.accounting.loans;

import com.sacco.mvp.domain.*;
import com.sacco.mvp.grouplending.dto.GroupCoverageDtos.*;
import com.sacco.mvp.grouplending.dto.GroupCycleDtos.SharedLiability;
import com.sacco.mvp.grouplending.service.*;
import com.sacco.mvp.service.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@EnabledIfEnvironmentVariable(named="MICROFINANCE_RECORDING_TEST_URL",matches="jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/microfinance_recording_test")
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class GroupCoverageModelsPostgresTest {
    final GroupSharedLoanPostgresTest w=new GroupSharedLoanPostgresTest();
    final GroupCyclePostgresTest g=w.s.s.g;final LoanRecordingPostgresTest f=w.f;
    GroupCoverageService coverage;UUID cycle;LocalDate day;
    @BeforeAll void start(){w.start();coverage=GroupCoveragePostgresTest.register(f);}
    @AfterAll void stop(){w.stop();}
    void advance(LocalDate date){day=date;when(f.context.getBean(ApplicationClock.class).today()).thenReturn(date);when(f.context.getBean(ApplicationClock.class).now()).thenReturn(date.atTime(12,0).atOffset(ZoneOffset.ofHours(3)));}
    void shared(SharedLiability rule){w.s.s.firstPaymentDate=LoanRecordingPostgresTest.TODAY.plusDays(1);w.s.s.setup();w.s.s.rule(rule);f.context.getBean(SaccoRegistryService.class).findActiveSacco(f.institution).orElseThrow().setSaccoName("Synthetic loan institution");var terms=w.s.s.form();terms.setTenureValue(3);cycle=w.s.cycle=g.cycles.create(f.actor,g.group,terms);g.cycles.submit(f.actor,cycle,terms);w.s.client=g.client(f.client);for(var person:List.of(f.client,g.second)){assertThat(g.consents.accept(g.client(person),cycle,true,"")).isNull();f.jdbc.update("insert into member_payment_details(member_id,destination_type,provider,account_holder_name,account_identifier,created_at,updated_at) values(?,'BANK_ACCOUNT','Synthetic bank','Synthetic account holder',?,now(),now())",person,"QA-"+person);}w.loan=g.cycles.sharedFacility(f.actor,cycle).orElseThrow().loanId();String hash=w.s.open();assertThat(w.s.agreements.confirm(w.s.client,cycle,hash,true,"")).isNull();var second=g.client(g.second);w.s.agreements.exportClient(second,cycle,Locale.ENGLISH);assertThat(w.s.agreements.confirm(second,cycle,w.s.agreements.packet(second,cycle).row().hash(),true,"")).isNull();f.context.getBean(MemberDirectoryService.class).find(f.actor.getMemberId()).orElseThrow().setSignatureText("Synthetic lender signature");f.jdbc.update("update members set signature_text='Synthetic lender signature' where id=?",f.actor.getMemberId());f.service.disburse(f.actor,w.funding());advance(w.s.s.firstPaymentDate.plusDays(16));}
    UUID call(Source source){var policy=new PolicyForm();policy.setNoticeDays(14);policy.setCaseDays(30);policy.setPromiseDays(7);policy.setEnabled(true);policy.setVerified(true);policy.setReference("Synthetic approved collection policy");var id=coverage.configure(f.actor,cycle,policy);var call=new CallForm();call.setSourceId(source.id());call.setSourceKind(source.kind());call.setPolicyId(id);call.setAmount(new BigDecimal("20.00"));call.setBorrowerNoticeDate(day.minusDays(15));call.setPersonNoticeDate(day.minusDays(15));call.setNoticesVerified(true);call.setNoticeLanguage("BOTH");call.setBorrowerNoticeEvidence("Synthetic borrower service record");call.setPersonNoticeEvidence("Synthetic named person service record");return coverage.call(f.actor,cycle,call,GroupOrganizationPostgresTest.documentFile());}
    Detail detail(UUID id){return coverage.detail(f.actor,id,0,0,false);}
    @Test void proportionalSharedAllocationsStayVoluntaryAndWholeCashStillPostsOnlyOnce(){shared(SharedLiability.PROPORTIONAL);var source=coverage.sources(f.actor,cycle,0).rows().stream().filter(s->s.client().equals(f.client)).findFirst().orElseThrow();assertThat(source.kind()).isEqualTo("VOLUNTARY");UUID id=call(source);assertThat(detail(id).header().state()).isEqualTo("REQUESTED");var form=w.payment("30.00");form.setEffectiveDate(day);UUID payment=f.service.repay(f.actor,form).id();var link=new LinkForm();link.setPostingId(payment);link.setPayerVerified(true);link.setPayerEvidence("Synthetic verified signed shared payer");long journals=f.jdbc.queryForObject("select count(*) from gl_journal where sacco_id=?",Long.class,f.institution);coverage.link(f.actor,id,link);assertThat(detail(id).header().received()).isEqualByComparingTo("30.00");assertThat(detail(id).header().requested()).isEqualByComparingTo("20.00");assertThat(f.jdbc.queryForObject("select count(*) from gl_journal where sacco_id=?",Long.class,f.institution)).isEqualTo(journals);assertThat(f.jdbc.queryForObject("select count(*) from loan_ledgers where sacco_id=?",Long.class,f.institution)).isEqualTo(1);}
    @Test void jointLiabilityKeepsTheSignedWholeLoanCapAndOldCuredCasesNeverRevive(){shared(SharedLiability.JOINT_AND_SEVERAL);var source=coverage.sources(f.actor,cycle,0).rows().getFirst();assertThat(source.kind()).isEqualTo("JOINT");assertThat(source.cap()).isGreaterThan(new BigDecimal("1000.00"));UUID id=call(source);var repayment=w.payment("400.00");repayment.setEffectiveDate(day);f.service.repay(f.actor,repayment);assertThat(detail(id).header().state()).isEqualTo("CURED_ELSEWHERE");advance(day.plusMonths(1));assertThat(f.jdbc.queryForObject("select lending_coverage_due(?,?::date)",BigDecimal.class,w.loan,day)).isPositive();assertThat(detail(id).header().remainingDue()).isZero();assertThat(detail(id).header().unpaid()).isZero();assertThat(detail(id).header().received()).isZero();}
    @Test void reciprocalCoverageRequiresTheExactOtherPersonContributionAndTracksWholeCorrections(){
        g.setup();var form=g.form();form.setFirstPaymentDate(LoanRecordingPostgresTest.TODAY.plusDays(1));form.setTenureValue(3);cycle=g.cycles.create(f.actor,g.group,form);g.cycles.submit(f.actor,cycle,form);g.consents.accept(g.client(f.client),cycle,true,"");g.consents.accept(g.client(g.second),cycle,true,"");var participants=g.cycles.participants(f.actor,cycle);UUID loan=participants.stream().filter(x->x.clientId().equals(f.client)).findFirst().orElseThrow().loanId();for(var participant:participants)f.service.disburse(f.actor,f.post(participant.loanId(),"1000.00","RECIPROCAL-"+UUID.randomUUID()));advance(LoanRecordingPostgresTest.TODAY.plusDays(17));var source=coverage.sources(f.actor,cycle,0).rows().stream().filter(x->x.loan().equals(loan)).findFirst().orElseThrow();assertThat(source.kind()).isEqualTo("RECIPROCAL");assertThat(source.client()).isEqualTo(g.second);UUID id=call(source);
        var collection=f.context.getBean(GroupCollectionService.class);var cash=new com.sacco.mvp.grouplending.dto.GroupCollectionDtos.Form();cash.setEffectiveDate(day);cash.setMoneyAccountId(f.cash);cash.setReference("COVERAGE-"+UUID.randomUUID());cash.setRemitter("Synthetic actual group remitter");cash.setEvidence("Synthetic verified group contribution");var own=new com.sacco.mvp.grouplending.dto.GroupCollectionDtos.Row();own.setLoanId(loan);own.setPayerId(f.client);own.setAmount(new BigDecimal("10.00"));own.setDescription("Synthetic borrower contribution");var guarantor=new com.sacco.mvp.grouplending.dto.GroupCollectionDtos.Row();guarantor.setLoanId(loan);guarantor.setPayerId(g.second);guarantor.setAmount(new BigDecimal("30.00"));guarantor.setDescription("Synthetic actual guarantor contribution");cash.setRows(new ArrayList<>(List.of(own,guarantor)));cash.setPreviewHash(collection.preview(f.actor,cycle,cash).hash());var receipt=collection.post(f.actor,cycle,cash);var contribution=receipt.group().contributions().stream().filter(x->x.payerId().equals(g.second)).findFirst().orElseThrow();var link=new LinkForm();link.setPostingId(receipt.rows().getFirst().postingId());link.setPayerVerified(true);link.setPayerEvidence("Synthetic verified identified contribution");assertThatThrownBy(()->coverage.link(f.actor,id,link)).hasMessage("coverage.error.payment");link.setContributionId(receipt.group().contributions().getFirst().id());assertThatThrownBy(()->coverage.link(f.actor,id,link)).hasMessage("coverage.error.payer");link.setContributionId(contribution.id());coverage.link(f.actor,id,link);assertThat(detail(id).header().received()).isEqualByComparingTo("30.00");collection.reverse(f.operator("B1"),receipt.header().id(),UUID.randomUUID(),day,"Synthetic independent complete receipt correction");assertThat(detail(id).header().received()).isZero();assertThat(detail(id).payments().rows()).singleElement().satisfies(x->assertThat(x.reversedBy()).isNotNull());assertThat(f.jdbc.queryForObject("select count(*) from loan_ledgers where sacco_id=?",Long.class,f.institution)).isEqualTo(2);
    }
}
